using System;
class MonsterFormChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var form=new MonsterFormData();string error;Check(form.Valid(out error),"default form legal");form.Proficiency=-100;form.Bonus=int.MinValue;Check(form.Valid(out error),"negative proficiency and bonus allowed");var copy=form.Copy();copy.Abilities[0]=20;copy.Dice[0]=3;copy.Skills[0]=2;copy.DamageTypes[0]=12;Check(form.Abilities[0]==10&&form.Dice[0]==0&&form.Skills[0]==0&&form.DamageTypes[0]==0,"independent deep copied profile arrays");copy.Type=13;Check(!copy.Valid(out error),"original form cannot be undead");copy.Type=1;copy.Dice[0]=10001;Check(!copy.Valid(out error),"die budget validation");copy.Dice[0]=0;copy.Abilities[0]=2;Check(!copy.Valid(out error),"ability floor validation");var combat=new CombatState();combat.KillMonster();combat.Revive(false,1,true);combat.KillMonster();combat.Aftermath=true;combat.RestoreMonsterBase(200,18,3,10,45,false);Check(combat.Hp==0&&combat.MaxHp==200&&combat.MonsterBaseArmorClass==18&&combat.MonsterProficiencyBonus==3&&combat.MonsterAttackRange==10&&combat.MonsterBaseSpeed==45&&!combat.MonsterAttackIsMelee,"base restoration does not revive or heal before final spell resolution");Check(combat.Aftermath&&combat.MonsterRevivalPenalty==-4,"restoration preserves phase and existing ordeal");Check(combat.Revive(false,combat.MaxHp,false)&&combat.Hp==200&&combat.MonsterRevivalPenalty==-4,"true resurrection full hp without new ordeal or clearing existing effect");combat.UpdateMonsterBaseSpeed(int.MaxValue);combat.MonsterSpeedBonus=10;Check(combat.MonsterSpeed==int.MaxValue,"large speed does not overflow");var corpse=new CorpseClock();corpse.Observe(true,13,0);long limit=RevivalRules.Limit("True Resurrection");Check(RevivalRules.Error("True Resurrection",corpse,limit-600)=="","two hundred year deadline includes casting hour");Check(RevivalRules.CompletionError("True Resurrection",corpse,limit)=="","completion does not charge casting twice");corpse.Clear();corpse.Observe(true,13,0);Check(RevivalRules.Error("True Resurrection",corpse,limit-599)!="","over deadline rejected");combat.MonsterProficiencyBonus=int.MinValue;Check(combat.MonsterHitBonus==(long)int.MinValue-4,"negative proficiency plus ordeal cannot overflow");Console.WriteLine("PASS: complete independent form, bounds, original-type rules, base restoration, full revival, preservation and 200-year deadline");}
}
